 42	/// Complete page metadata together with the retained resident mapping.
 43	///
 44	/// The bytes in `page.memory` may have been discarded by the OS while this
 45	/// value is in compressed state. They must not be read until `restore` has
 46	/// successfully decoded the page.
 47	page: TerminalPage,
 48	
 49	/// Exact raw LZ4 block for `page.memory`.
 50	encoded: []u8,
 51	
 52	/// Allocator which owns `encoded`.
 53	///
 54	/// The allocator's backing state must outlive this compressed page. Storing
 55	/// the allocator here lets a PageList node restore and discard its compressed
 56	/// state without needing a reference back to the PageList.
 57	alloc: Allocator,
 58	
 59	/// Return the largest scratch buffer that can produce a useful compressed
 60	/// representation for `raw_len` bytes.
 61	///
 62	/// This is deliberately smaller than the general LZ4 compression bound. The
 63	/// compressed representation includes an additional slice compared to a
 64	/// resident terminal page, so an encoded block which fills more than this
 65	/// buffer cannot reduce resident memory. Limiting the output here lets a
 66	/// PageList borrow a standard page-pool item as scratch instead of retaining a
 67	/// larger, compression-bound allocation.
 68	///
 69	/// Callers are expected to reuse the scratch memory when practical. The
 70	/// scratch buffer and hash table are never retained by this type.
 71	pub fn requiredScratch(raw_len: usize) lz4.CompressError!usize {
 72	    // Validate the codec's input limit before doing arithmetic based on the
 73	    // raw size. The bound itself is intentionally not returned; see above.
 74	    _ = try lz4.compressBound(raw_len);
 75	
 76	    const representation_overhead = @sizeOf(Page) - @sizeOf(TerminalPage);
 77	    if (raw_len <= representation_overhead) return 0;
 78	
 79	    // The savings comparison is strict, so reserve one fewer byte than the
 80	    // break-even encoded size.
 81	    return raw_len - representation_overhead - 1;
 82	}
 83	
 84	/// Create a compressed representation of `source`.
 85	///
 86	/// `source` is not modified and continues to own its backing allocation. The
 87	/// scratch buffer must be at least `requiredScratch(source.memory.len)` bytes.
 88	/// It must not overlap the source memory. On success, the returned value aliases
 89	/// the source's resident mapping and owns only its exact-sized `encoded`
 90	/// allocation. The allocator and its backing state must remain valid until
 91	/// `deinit` is called.
 92	///
 93	/// Returns null if retaining the compressed representation would not use less
 94	/// memory than the resident representation. An `OutputTooSmall` result from
 95	/// the codec also means the encoding crossed that break-even point and is
 96	/// therefore returned as null. This comparison includes the in-memory size of
 97	/// both representation structs but does not include allocator metadata or the
 98	/// retained virtual address range.
 99	pub fn init(
100	    alloc: Allocator,
101	    source: *const TerminalPage,
102	    scratch: []u8,
103	    table: *lz4.HashTable,
104	) (Allocator.Error || lz4.CompressError)!?Page {
105	    const required = try requiredScratch(source.memory.len);
106	    if (scratch.len < required) return error.OutputTooSmall;
107	    if (required == 0) return null;
108	
109	    // Page memory is an opaque snapshot containing structs whose padding has
110	    // no semantic value. Assigning those structs can leave their padding
111	    // undefined in Memcheck even though every byte is addressable and must be
112	    // preserved by compression. Mark the complete byte representation as
113	    // defined at this boundary so that undefined padding does not propagate
114	    // through the codec and obscure real Valgrind failures.
115	    if (std.valgrind.runningOnValgrind() > 0)
116	        std.valgrind.memcheck.makeMemDefined(source.memory);
117	
118	    const encoded_len = lz4.compress(
119	        source.memory,
120	        scratch[0..required],
121	        table,
122	    ) catch |err| switch (err) {
123	        // The scratch limit is the largest representation worth retaining.
124	        // Running out of room therefore means compression cannot save memory,
125	        // rather than that the caller failed to provide the documented size.
126	        error.OutputTooSmall => return null,
127	        error.InputTooLarge => return err,
128	    };
129	
130	    // requiredScratch already accounts for the representation structs. The
131	    // retained virtual range contributes no resident bytes after PageList
132	    // decommits it.
133	    assert(@sizeOf(Page) + encoded_len <
134	        @sizeOf(TerminalPage) + source.memory.len);
135	
136	    return .{
137	        .page = source.*,
138	        .encoded = try alloc.dupe(u8, scratch[0..encoded_len]),
139	        .alloc = alloc,
140	    };
141	}
142	
143	/// Free the encoded block.
144	///
145	/// This intentionally does not free `page.memory`. The PageList node which
146	/// supplied the source page continues to own that pool or heap allocation.
147	pub fn deinit(self: *Page) void {
148	    self.alloc.free(self.encoded);
149	    self.* = undefined;
150	}
151	
152	/// Restore the embedded terminal page into its retained resident mapping.
153	///
154	/// The caller must recommit `page.memory` before calling this on platforms
155	/// which require an explicit recommit operation. The compressed value remains
156	/// valid whether decoding succeeds or fails, allowing the caller to retry or
157	/// discard it. On success the returned page aliases the same resident mapping;
158	/// it does not own a new allocation.
159	pub fn restore(self: *const Page) lz4.DecompressError!TerminalPage {
160	    const result = self.page;
161	    _ = try lz4.decompress(self.encoded, result.memory);
162	    return result;
163	}
164	
165	/// Clone this page into caller-owned memory without restoring its mapping.
166	///
167	/// `memory` must be at least as large as the retained page mapping. Decoding
168	/// writes only to that buffer, so both the discarded contents of `page.memory`
169	/// and this value's encoded representation remain unchanged. The returned Page
170	/// borrows `memory`; the caller must keep it alive for the Page's lifetime and
171	/// release it directly rather than calling `TerminalPage.deinit`.
172	pub fn cloneBuf(
173	    self: *const Page,
174	    memory: []align(std.heap.page_size_min) u8,
175	) lz4.DecompressError!TerminalPage {
176	    assert(memory.len >= self.page.memory.len);
177	
178	    // Page internals are offsets into the backing buffer, so all metadata can
179	    // be copied verbatim when paired with an equally laid-out mapping.
180	    var result = self.page;
181	    result.memory = memory[0..self.page.memory.len];
182	    _ = try lz4.decompress(self.encoded, result.memory);
183	    return result;
184	}
