  1401	    /// Convert a hyperlink into a page entry, returning the ID.
  1402	    ///
  1403	    /// This does not de-dupe any strings, so if the URI, explicit ID,
  1404	    /// etc. is already in the strings table this will duplicate it.
  1405	    ///
  1406	    /// To release the memory associated with the given hyperlink,
  1407	    /// release the ID from the `hyperlink_set`. If the refcount reaches
  1408	    /// zero and the slot is needed then the context will reap the
  1409	    /// memory.
  1410	    pub fn insertHyperlink(
