  5152	inline fn createPageExt(
  5153	    pool: *MemoryPool,
  5154	    opts: CreatePage,
  5155	    serial: *u64,
  5156	    total_size: ?*usize,
  5157	) Allocator.Error!*List.Node {
  5158	    var page = try pool.nodes.create();
  5159	    errdefer pool.nodes.destroy(page);
  5160	
  5161	    const layout = Page.layout(opts.cap);
  5162	    const pooled = !opts.exact_size and layout.total_size <= std_size;
  5163	    const page_alloc = pool.pages.allocator;
  5164	
  5165	    // It would be better to encode this into the Zig error handling
  5166	    // system but that is a big undertaking and we only have a few
  5167	    // centralized call sites so it is handled on its own currently.
  5168	    assert(layout.total_size <= size.max_page_size);
  5169	
  5170	    // Our page buffer comes from our standard memory pool if it
  5171	    // is within our standard size since this is what the pool
  5172	    // dispenses. Otherwise, we use the heap allocator to allocate.
  5173	    const page_buf = if (pooled) buf: {
  5174	        const buf = try pool.pages.create();
  5175	        terminal_mem.recommit(buf);
  5176	        break :buf buf;
  5177	    } else try page_alloc.alignedAlloc(
  5178	        u8,
  5179	        .fromByteUnits(std.heap.page_size_min),
  5180	        layout.total_size,
  5181	    );
  5182	    errdefer if (pooled)
  5183	        pool.pages.destroy(page_buf)
  5184	    else
  5185	        page_alloc.free(page_buf);
  5186	
  5187	    // In runtime safety modes, allocators fill with 0xAA. On freestanding
  5188	    // (WASM), the WasmAllocator reuses freed slots without zeroing.
  5189	    //
  5190	    // Otherwise, we rely on pool item buffers being zeroed: fresh items
  5191	    // come from the OS page allocator (zeroed pages), destroyNodeExt
  5192	    // zeroes buffers before returning them to the pool, and the pool
  5193	    // never writes into its items (see PagePool).
  5194	    if (comptime std.debug.runtime_safety or builtin.target.os.tag == .freestanding)
  5195	        @memset(page_buf, 0);
  5196	
  5197	    page.* = .{
  5198	        .data = .{ .resident = .initBuf(.init(page_buf), layout) },
  5199	        .serial = serial.*,
  5200	        .owned = if (pooled) .pool else .heap,
  5201	    };
  5202	    page.page().size.rows = 0;
  5203	    serial.* += 1;
  5204	
  5205	    if (total_size) |v| {
  5206	        // Accumulate page size now. We don't assert or check max size
  5207	        // because we may exceed it here temporarily as we are allocating
  5208	        // pages before destroy.
  5209	        v.* += page_buf.len;
  5210	    }
  5211	
  5212	    return page;
  5213	}
