  5215	/// Temporary output memory used while creating a compressed page.
  5216	///
  5217	/// Standard-sized output borrows a page-pool item so repeated compression can
  5218	/// reuse the same virtual mapping. Oversized pages use a temporary allocation
  5219	/// from the page allocator and release it immediately after compression.
  5220	///
  5221	/// A borrowed item goes back to the pool through zero-mode decommit, which
  5222	/// only has to clear the bytes the encoder wrote. Callers therefore pass the
  5424	/// mode visits every currently eligible node once without using incremental
  5425	/// state.
  5426	///
  5427	/// PageList tracks mutations which require a later incremental pass in its
  5428	/// compression state. On supported targets, full compression returns
  5429	/// `complete`, indicating that it has no continuation to schedule rather than
  5430	/// that every page was compressed.
  5431	pub fn compress(
  5432	    self: *PageList,
  5433	    mode: enum { incremental, drain, full },
  5434	) IncrementalCompressionResult {
  5435	    return switch (mode) {
  5436	        .incremental => self.compressIncremental(),
  5437	        .drain => while (true) switch (self.compressIncremental()) {
  5438	            .pending => continue,
  5439	            .complete => break .complete,
  5440	            .unsupported => break .unsupported,
  5441	        },
  5442	        .full => full: {
  5443	            // Match incremental mode's unsupported result. Full compression
  5444	            // has no useful work to perform without strict reclamation.
  5445	            if (!terminal_mem.canReclaim(.strict)) {
  5446	                self.page_compression.reset();
  5447	                break :full .unsupported;
  5448	            }
  5449	
  5450	            self.compressFull();
  5451	
  5452	            // Full compression has no continuation. Discard any partial
  5453	            // incremental cursor so later activity starts at the oldest page.
  5454	            self.page_compression.reset();
  5455	
  5456	            break :full .complete;
  5457	        },
  5458	    };
