 18	/// Unit is the type we use per tabstop unit (see file docs).
 19	const Unit = u8;
 20	const unit_bits = @bitSizeOf(Unit);
 21	
 22	/// The number of columns we preallocate for. This is kind of high which
 23	/// costs us some memory, but this is more columns than my 6k monitor at
 24	/// 12-point font size, so this should prevent allocation in almost all
 25	/// real world scenarios for the price of wasting at most
 26	/// (columns / sizeOf(Unit)) bytes.
 27	const prealloc_columns = 512;
 28	
 29	/// The number of entries we need for our preallocation.
 30	const prealloc_count = prealloc_columns / unit_bits;
 31	
 32	/// We precompute all the possible masks since we never use a huge bit size.
 33	const masks = blk: {
 34	    var res: [unit_bits]Unit = undefined;
 35	    for (res, 0..) |_, i| {
 36	        res[i] = @shlExact(@as(Unit, 1), @as(u3, @intCast(i)));
 37	    }
 38	
 39	    break :blk res;
 40	};
 41	
 42	/// The number of columns this tabstop is set to manage. Use resize()
 43	/// to change this number.
 44	cols: usize = 0,
 45	
 46	/// Preallocated tab stops.
 47	prealloc_stops: [prealloc_count]Unit = @splat(0),
 48	
 49	/// Dynamically expanded stops above prealloc stops.
 50	dynamic_stops: []Unit = &[0]Unit{},
 51	
 52	/// Returns the entry in the stops array that would contain this column.
 53	inline fn entry(col: usize) usize {
 54	    return col / unit_bits;
 55	}
 56	
 57	inline fn index(col: usize) usize {
 58	    return @mod(col, unit_bits);
 59	}
