2765	            self.cursor.page_pin.node.page().appendGrapheme(
2766	                self.cursor.page_row,
2767	                reloaded_cell,
2768	                cp,
2769	            ) catch |err2| {
2770	                comptime assert(@TypeOf(err2) == error{OutOfMemory});
2771	                // This should never happen because we just increased capacity.
2772	                // Log loudly but still return an error so we don't just
2773	                // crash.
